mapper.select:
SELECT u.username AS username, u.user_profile_url AS userProfileUrl, COALESCE(tp.career, '') AS career,
/* ✅ 누적 수강생수: enrollments 기준으로 안전하게 집계 */ COALESCE(( SELECT COUNT(1) FROM enrollments e JOIN trainings t2 ON t2.training_id = e.training_id WHERE t2.trainer_id = u.user_id ), 0) AS totalTraineeCount,
/* 평균 별점: 승인된 강의만 평균 */ COALESCE(( SELECT AVG(NULLIF(t3.average_rating, 0)) FROM trainings t3 WHERE t3.trainer_id = u.user_id AND t3.approval_status = '승인' ), 0) AS totalAverageRating
FROM users u LEFT JOIN trainer_profiles tp ON tp.trainer_id = u.user_id WHERE u.user_id = #{trainerId}
